{"code": "
fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"
info = simulate_move(fen)
legal = sorted(info["legal_moves"])
print(legal)

def evaluate(fen):
    info = simulate_move(fen)
    if info["game_over"]:
        w = info.get("winner")
        r = info.get("result")
        if w == "white":
            return 100000
        elif w == "black":
            return -100000
        else:
            return 0
    b = info["board"]
    squares = [(r, c) for r in range(8) for c in range(8)]
    score = 0
    piece_vals = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0,
                  'p':100,'n':320,'b':330,'r':500,'q':900,'k':0}
    for r in range(8):
        for c in range(8):
            p = b[r][c]
            if p == '.':
                continue
            v = piece_vals[p]
            if p.isupper():
                score += v
                if (r, c) in [(3,3),(3,4),(4,3),(4,4)]:
                    score += 12
            else:
                score -= v
                if (r, c) in [(3,3),(3,4),(4,3),(4,4)]:
                    score -= 12
    # check
    if info.get("in_check"):
        if info["turn"] == "black":
            score += 25
        else:
            score -= 25
    return score

best = None
best_score = None
for mv in legal:
    aw = simulate_move(fen, mv)
    if aw["game_over"]:
        sc = evaluate(aw["fen"])
    else:
        replies = sorted(aw["legal_moves"])
        sc = None
        for rep in replies:
            pos = simulate_move(aw["fen"], rep)
            s = evaluate(pos["fen"])
            if sc is None or s < sc:
                sc = s
    print(mv, sc)
    if best_score is None or sc > best_score:
        best = mv
        best_score = sc
print("BEST", best, best_score)
play_move(best)
"}

